code='''from collections import Counter, deque


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    background = Counter(v for row in g for v in row).most_common(1)[0][0]
    seen = set()
    for r in range(h):
        for c in range(w):
            if g[r][c] == background or (r, c) in seen:
                continue
            color = g[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and g[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            y0, y1 = min(y for y,x in cells), max(y for y,x in cells)
            x0, x1 = min(x for y,x in cells), max(x for y,x in cells)
            if y1-y0 < 2 or x1-x0 < 2:
                continue
            border = {(y,x) for y,x in cells if y in (y0,y1) or x in (x0,x1)}
            if set(cells) != border:
                continue
            if any(g[y][x] != background for y in range(y0+1,y1) for x in range(x0+1,x1)):
                continue
            fill = 7 if max(y1-y0+1, x1-x0+1) <= 5 else 2
            for y in range(y0+1,y1):
                for x in range(x0+1,x1):
                    g[y][x] = fill
    return g
'''
